    n = n + 1
    n = n * 10
    if n == 20 { io.println("let-ok") } else { io.println("let-bad") }

    let a: Int64 = 1
    let b: Int64 = a
    b = 2
    if a == 1 && b == 2 { io.println("alias-ok") } else { io.println("alias-bad") }

    return Ok(())
}
